package com.nexuspc.catalog.category;
import com.nexuspc.catalog.dto.*; import com.nexuspc.catalog.product.ProductRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class CategoryService { private final CategoryRepository repo; private final ProductRepository products; public CategoryService(CategoryRepository repo,ProductRepository products){this.repo=repo;this.products=products;}
 public List<CategoryResponse> all(){return repo.findAll().stream().map(this::response).toList();} public CategoryResponse get(String slug){return response(repo.findBySlug(slug).orElseThrow(()->new NoSuchElementException("Category not found")));}
 @Transactional public CategoryResponse create(CategoryRequest r){if(repo.existsBySlug(r.slug()))throw new IllegalArgumentException("Category slug already exists");return response(repo.save(new Category(r.name(),r.slug(),r.description(),r.icon(),r.image())));}
 @Transactional public CategoryResponse update(Long id,CategoryRequest r){Category c=repo.findById(id).orElseThrow(()->new NoSuchElementException("Category not found"));if(!c.getSlug().equals(r.slug())&&repo.existsBySlug(r.slug()))throw new IllegalArgumentException("Category slug already exists");c.update(r.name(),r.slug(),r.description(),r.icon(),r.image());return response(c);}
 @Transactional public void delete(Long id){if(!repo.existsById(id))throw new NoSuchElementException("Category not found");if(products.countByCategoryId(id)>0)throw new IllegalArgumentException("Cannot delete category with products");repo.deleteById(id);}
 private CategoryResponse response(Category c){return new CategoryResponse(c.getId(),c.getSlug(),c.getName(),c.getDescription(),c.getIcon(),products.countByCategoryId(c.getId()),c.getImage());}}
